import { STATE_TAX_TABLE } from "./stateTaxTable";
import type { DefaultRecord, IsoDate, MoneyCents, RateMicros } from "./types";

/**
 * Registry of every illustrative default (PRD 9.2 and 9.3).
 * Money is integer cents, rates are integer millionths.
 * Changing a value requires a new `asOf` in the same change; the guard test
 * in defaults.test.ts fails otherwise.
 */

/** A default older than this many days is shown as "May be out of date". */
export const STALE_AFTER_DAYS = 365;

const MS_PER_DAY = 86_400_000;

const toUtcDay = (iso: IsoDate): number => {
	const [year, month, day] = iso.split("-").map(Number);
	return Date.UTC(year, month - 1, day);
};

/**
 * True when `asOf` is more than STALE_AFTER_DAYS before `today`.
 * Exactly 365 days is not stale. Staleness never blocks a calculation.
 */
export const isStale = (asOf: IsoDate, today: Date = new Date()): boolean => {
	const todayUtc = Date.UTC(
		today.getUTCFullYear(),
		today.getUTCMonth(),
		today.getUTCDate(),
	);
	return (todayUtc - toUtcDay(asOf)) / MS_PER_DAY > STALE_AFTER_DAYS;
};

export interface IndexPreset {
	id: "flat" | "plus-one-per-year" | "shock";
	label: string;
}

const AS_OF = "2026-10-30";

export const DEFAULTS = {
	stateTaxRates: STATE_TAX_TABLE,
	homeownersInsurance: {
		/** Annual, flat. Does not scale with home price. $2,400.00 per year. */
		value: 240000 as MoneyCents,
		source:
			"Four public 2026 estimates between $2,377 and $2,543, based on about $300,000 of dwelling coverage",
		asOf: AS_OF,
		confidence: "moderate",
	},
	pmiRate: {
		/** Annual rate on the loan amount. 0.75% per year. */
		value: 7500 as RateMicros,
		source:
			"Midpoint of the commonly cited 0.5% to 1.0% range. No authoritative rate matrix was found.",
		asOf: AS_OF,
		confidence: "low",
	},
	armTerms: {
		value: {
			/** 2.75% margin. */
			marginMicros: 27500 as RateMicros,
			/** Caps 2/1/5 in rate points: initial 2%, periodic 1%, lifetime 5%. */
			initialCapMicros: 20000 as RateMicros,
			periodicCapMicros: 10000 as RateMicros,
			lifetimeCapMicros: 50000 as RateMicros,
		},
		source:
			"Author's knowledge of typical 5/6 SOFR terms. Not checked against a Loan Estimate.",
		asOf: AS_OF,
		confidence: "low",
	},
	dtiThresholds: {
		value: {
			/** 28% front-end. */
			frontEndMicros: 280000 as RateMicros,
			/** 36% back-end. */
			backEndMicros: 360000 as RateMicros,
		},
		source: "Common industry rules of thumb. Not verified.",
		asOf: AS_OF,
		confidence: "moderate",
	},
	indexPathPresets: {
		value: [
			{ id: "flat", label: "Flat" },
			{ id: "plus-one-per-year", label: "+1 point per year" },
			{ id: "shock", label: "Shock" },
		] as IndexPreset[],
		source: "Product choice",
		asOf: AS_OF,
		confidence: "not-applicable",
	},
} satisfies Record<string, DefaultRecord<unknown>>;
EOF
cat > defaults.test.ts <<'EOF'
import { describe, expect, it } from "vitest";
import { DEFAULTS, isStale, STALE_AFTER_DAYS } from "./defaults";
import { STATE_TAX_COLUMN_LABEL, STATE_TAX_TABLE } from "./stateTaxTable";

const daysBefore = (today: Date, days: number): string => {
	const d = new Date(today.getTime() - days * 86_400_000);
	return d.toISOString().slice(0, 10);
};

describe("isStale", () => {
	const today = new Date("2027-11-01T12:00:00Z");

	it("uses a 365 day limit", () => {
		expect(STALE_AFTER_DAYS).toBe(365);
	});

	it("is false at 364 and 365 days", () => {
		expect(isStale(daysBefore(today, 364), today)).toBe(false);
		expect(isStale(daysBefore(today, 365), today)).toBe(false);
	});

	it("is true at 366 days", () => {
		expect(isStale(daysBefore(today, 366), today)).toBe(true);
	});

	it("is false for a same-day or future date", () => {
		expect(isStale(daysBefore(today, 0), today)).toBe(false);
	});
});

describe("defaults registry", () => {
	it("gives every record a value, source, ISO asOf and confidence", () => {
		for (const record of Object.values(DEFAULTS)) {
			expect(record.value).toBeDefined();
			expect(record.source.length).toBeGreaterThan(0);
			expect(record.asOf).toMatch(/^\d{4}-\d{2}-\d{2}$/);
			expect(record.confidence.length).toBeGreaterThan(0);
		}
	});

	it("marks ARM and PMI as low confidence", () => {
		expect(DEFAULTS.armTerms.confidence).toBe("low");
		expect(DEFAULTS.pmiRate.confidence).toBe("low");
	});

	it("exports the tax table from its own module with the column label", () => {
		expect(DEFAULTS.stateTaxRates).toBe(STATE_TAX_TABLE);
		expect(STATE_TAX_COLUMN_LABEL).toBe("Illustrative new-buyer estimate");
	});

	// Guard (PRD 9.3): value and asOf must change together. If you change a
	// value, you must set a new asOf in the record and update this snapshot.
	it("matches the committed value and asOf snapshot", () => {
		const current = Object.fromEntries(
			Object.entries(DEFAULTS).map(([key, r]) => [
				key,
				{ value: r.value, asOf: r.asOf },
			]),
		);
		expect(current).toMatchInlineSnapshot();
	});
});
EOF
cd ../../.. && export PATH=$HOME/.local/bin:$PATH && yarn test 2>&1 | tail -15

